    {
      "term": "ser",
      "category": "Verb",
      "definition": "Says what or who someone is: name, job, where they're from, what they're like.",
      "example": "Soy Ana y soy de Lima. — I'm Ana, and I'm from Lima.",
      "mental_model": "Ser is the label on the box; estar is a photo of the box right now."
